{
  "anomaly_detected": true,
  "confidence": 0.98,
  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["FCC2", "NAVC2", "R39"],
      "pins": ["FCC2.48", "FCC2.73", "NAVC2.31", "NAVC2.47"],
      "nets": ["NET0151", "NET0050", "NET0005", "NET0051", "+3V3"],
      "observed": "The STM32H753 VCAP pins are assigned to NET0151 and NET0050, which are also routed to the UART3_FCC2 connector. The STM32F405 VCAP_1 is on NET0005, which is pulled up to +3V3 through R39; VCAP_2 is on NET0051. Neither MCU shows the required VCAP decoupling capacitors to ground.",
      "expected": "Each MCU's VCAP regulator output should have its specified capacitor to ground and should not be connected to external signal connectors or pulled up to +3V3.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "FCC2 pins 48 and 73 are labelled VCAP and connected to NET0151 and NET0050; see Flight Control Computer, page 2."
        },
        {
          "source": "schematic",
          "quote": "UART3_FCC2 connector pins 3 and 4 are NET0151 and NET0050; see FCC Peripherals, page 5."
        },
        {
          "source": "schematic",
          "quote": "NAVC2 pins 31 and 47 are labelled VCAP_1 and VCAP_2; NET0005 connects through R39 4k7 to +3V3, and no VCAP capacitors are shown; see Navigation Computer, page 3."
        },
        {
          "source": "spec",
          "quote": "The FCC is populated with an STM32H753VITx ... and the NAVC with an STM32F405RGTx."
        }
      ],
      "impact": "The MCUs' internal core regulators may be unstable or unable to operate correctly. The FCC VCAP outputs are also exposed on a connector, where external loading could further disrupt or damage the MCU.",
      "confidence": 0.98
    }
  ],
  "summary": "The schematic misuses the VCAP pins on both MCUs: required decoupling is absent, and the FCC VCAP nets are exposed on a connector while a NAVC VCAP net is pulled toward +3V3. This is likely to prevent reliable MCU operation."
}

